41	    /** Number of leading SHA-256 hex characters that make up a household identifier. */
42	    private static final int ID_LENGTH = 12;
43	
44	    private final ClinicService clinicService;
45	
46	    public Households(ClinicService clinicService) {
47	        this.clinicService = clinicService;
48	    }
49	
50	    /**
51	     * Existing owners that share {@code candidate}'s household (same {@link #householdId(Owner)
52	     * household identifier}). Intended for a not-yet-persisted candidate, so the candidate never
53	     * appears in the result.
54	     */
55	    public List<Owner> findMembers(Owner candidate) {
56	        String householdId = householdId(candidate);
57	        return clinicService.findOwnerByLastNameIgnoreCase(candidate.getLastName()).stream()
58	            .filter(existing -> householdId.equals(householdId(existing)))
59	            .toList();
60	    }
61	
62	    /**
63	     * The stable identifier every owner in {@code owner}'s household shares: the first
64	     * {@value #ID_LENGTH} hex characters of {@code SHA-256(normalizedLastName + '|' + postcode)}.
65	     * The same last name and postcode always yield the same id.
66	     */
67	    public String householdId(Owner owner) {
68	        String key = normalize(owner.getLastName()) + "|" + segment(owner.getPostcode());
69	        return sha256Hex(key).substring(0, ID_LENGTH);
70	    }
71	
72	    /**
73	     * Canonicalize the last name for household comparison: {@code null} becomes empty, surrounding
74	     * whitespace is trimmed, internal whitespace runs collapse to a single space, and the result
75	     * is lower-cased.
76	     */
