78	        if (value == null) {
79	            return "";
80	        }
81	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
82	    }
83	
84	    private String segment(String value) {
85	        return value == null ? "" : value;
86	    }
87	
88	    private String sha256Hex(String value) {
89	        try {
90	            byte[] digest = MessageDigest.getInstance("SHA-256")
91	                .digest(value.getBytes(StandardCharsets.UTF_8));
